"def test_claim_users_with_mixed_input(enterprise, enterprise_mocks):
    users = {
        'usrFakeUserId1': 'managed',
        'someone@example.com': 'unmanaged',
        'usrFakeUserId2': 'unmanaged',
        'another@example.com': 'managed'
    }
    result = enterprise.claim_users(users)

    assert isinstance(result, ManageUsersResponse)
    assert enterprise_mocks.claim_users.call_count == 1

    expected_payload = {
        'users': [
            {'id': 'usrFakeUserId1', 'state': 'managed'},
            {'email': 'someone@example.com', 'state': 'unmanaged'},
            {'id': 'usrFakeUserId2', 'state': 'unmanaged'},
            {'email': 'another@example.com', 'state': 'managed'}
        ]
    }
    assert enterprise_mocks.claim_users.last_request.json() == expected_payload"

"def test_users_with_mixed_input_and_collaborations(enterprise, requests_mock):
    # Mock the API response
    mock_response = {
        'users': [
            {
                'id': 'usrABC123',
                'email': 'user1@example.com',
                'name': 'User 1',
                'state': 'provisioned',
                'isSsoRequired': False,
                'isTwoFactorAuthEnabled': True,
                'collaborations': {
                    'workspaces': [
                        {'id': 'wspc1', 'name': 'Workspace 1'},
                        {'id': 'wspc2', 'name': 'Workspace 2'}
                    ]
                }
            },
            {
                'id': 'usrDEF456',
                'email': 'user2@example.com',
                'name': 'User 2',
                'state': 'provisioned',
                'isSsoRequired': True,
                'isTwoFactorAuthEnabled': False,
                'collaborations': {
                    'workspaces': [
                        {'id': 'wspc3', 'name': 'Workspace 3'}
                    ]
                }
            }
        ]
    }
    requests_mock.get(f'{enterprise.url}/users', json=mock_response)

    # Test with mixed input of IDs and emails
    mixed_input = ['usrABC123', 'user2@example.com']
    results = enterprise.users(mixed_input, collaborations=True)

    # Assertions
    assert len(results) == 2
    assert all(isinstance(user, UserInfo) for user in results)
    assert [user.id for user in results] == ['usrABC123', 'usrDEF456']
    assert [user.email for user in results] == ['user1@example.com', 'user2@example.com']
    assert [user.state for user in results] == ['provisioned', 'provisioned']
    assert [user.is_sso_required for user in results] == [False, True]
    assert [user.is_two_factor_auth_enabled for user in results] == [True, False]

    # Check if collaborations attribute exists
    assert all(hasattr(user, 'collaborations') for user in results)

    # If collaborations are present, check their structure
    if results[0].collaborations:
        assert hasattr(results[0].collaborations, 'workspaces')
        assert isinstance(results[0].collaborations.workspaces, list)
    if results[1].collaborations:
        assert hasattr(results[1].collaborations, 'workspaces')
        assert isinstance(results[1].collaborations.workspaces, list)

    # Verify API call
    last_request = requests_mock.last_request
    assert last_request.qs == {
        'id': ['usrABC123'],
        'email': ['user2@example.com'],
        'include': ['collaborations']
    }"

"def test_options_to_json_and_params_full_coverage():
    options = {
        'use_field_ids': True,
        'sort': ['Name', '-Phone'],
        'fields': ['Name', 'Phone', 'Name'],
        'formula': ' NOT(1) ',
        'view': 'SomeView',
        'user_locale': 'en-US'  # This option is not supported via POST
    }

    expected_json = {
        'returnFieldsByFieldId': True,
        'sort': [
            {'field': 'Name', 'direction': 'asc'},
            {'field': 'Phone', 'direction': 'desc'}
        ],
        'fields': ['Name', 'Phone'],
        'filterByFormula': 'NOT(1)',
        'view': 'SomeView'
    }

    expected_params = {'userLocale': 'en-US'}

    result_json, result_params = options_to_json_and_params(options)

    assert result_json == expected_json
    assert result_params == expected_params"
